import { HTTP_REDIRECT_FOUND } from "../../utils/index.js";
/** Context for middleware. */
export class MiddlewareContext {
    req;
    request;
    identity;
    applicationIdentity;
    env;
    executionCtx;
    var = {};
    store = new Map();
    constructor(req, env = {}, executionCtx, identity = null) {
        this.req = req;
        this.request = req; // Alias for compatibility
        this.identity = identity;
        this.applicationIdentity = identity;
        this.env = env;
        this.executionCtx = executionCtx;
    }
    json(object, init) {
        return Response.json(object, init);
    }
    respondWithContent(body, contentType, init) {
        return new Response(body, {
            ...init,
            headers: {
                "content-type": contentType,
                ...init?.headers,
            },
        });
    }
    text(text, init) {
        return this.respondWithContent(text, "text/plain; charset=utf-8", init);
    }
    html(html, init) {
        return this.respondWithContent(html, "text/html; charset=utf-8", init);
    }
    redirect(location, status = HTTP_REDIRECT_FOUND) {
        return new Response(null, {
            status,
            headers: { Location: location },
        });
    }
    set(key, value) {
        this.store.set(key, value);
    }
    get(key) {
        return this.store.get(key);
    }
}
